const int LDR_PIN = A0;
const int LED_PIN = 9;

// Adjust this threshold if needed based on room brightness (0-1023)
const int DARK_THRESHOLD = 400;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(LDR_PIN, INPUT);
  Serial.begin(9600);
}

void loop() {
  int lightLevel = analogRead(LDR_PIN);
  Serial.print("Current light level: ");
  Serial.println(lightLevel);

  // When the sensor is in the dark, the analog reading drops below the threshold
  if (lightLevel < DARK_THRESHOLD) {
    digitalWrite(LED_PIN, HIGH); // Turn night light ON
  } else {
    digitalWrite(LED_PIN, LOW);  // Turn night light OFF
  }

  delay(200);
}

